                    { { t = "In Steamwheedle Port accept " }, { q = "The God Hakkar", id = 3528 }, { t = " from " }, { n = "Yeh'kinya", id = 8579 }, { t = "; the prerequisite is " }, { q = "The Ancient Egg", id = 4787 }, { t = " from Zul'Farrak." } },
                    { { t = "In the Barrens at 62,38, accept " }, { q = "Zapper Fuel", id = 4146 }, { t = " from " }, { n = "Liv Rizzlefix", id = 8496 }, { t = "; it needs 5 " }, { i = "Atal'ai Haze", id = 11318 }, { t = "." } },
                    { { t = "The quests are spread across four zones; collect them all before going in, and fill in any you're missing first." } },
                },
            },
            {
                hd = "Inside the Dungeon",
                st = {
                    { { t = "The entrance hall has four passages from left to right; the leftmost goes straight to the green dragons and is also the exit after you finish." } },
                    { { t = "The second leads to the troll guardians' galleries, the third to the statue puzzle, and the fourth to the Altar of Hakkar on the lowest level." } },
                    { { t = "Take the rightmost passage first and go down the long spiral stairs to the bottom level." } },
                    { { t = "Find the Altar of Hakkar at the edge of the Pit of Refuse to complete " }, { q = "Into the Depths", id = 3446 }, { t = "." } },
                    { { t = "Clear every mob around the altar: oozes drop " }, { i = "Atal'ai Haze", id = 11318 }, { t = ", collect 5; all enemies drop " }, { i = "Fetish of Hakkar", id = 6181 }, { t = ", collect 20." } },
                    { { t = "Return to the entrance and take the third passage; at the fork go down to the Hall of Solitude and clear the six doorways inside the ring one by one." } },
                    { { t = "After clearing, click the serpent statues in order: 6, 12, 8, 5, 11 and 2 o'clock." } },
                    { { t = "With all six statues lit, the Idol of Hakkar rises from the bottom and Atal'alarion spawns; kill him and click the idol to complete " }, { q = "Secret of the Circle", id = 3447 }, { t = "." } },
                    { { t = "Return to the entrance and take the second passage down to the fourth level; clear in a circle, enter every door on both sides, and kill all six troll guardians." } },
                    { { t = "After the six guardians are cleared, Jammal'an speaks; jump down from the gallery to engage. He mind-controls, so spread out if someone is controlled." } },
                    { { t = "Loot " }, { i = "Head of Jammal'an", id = 6212 }, { t = " from the body; take out the small green boss next to him too." } },
                    { { t = "Go to the Green Dragon Hall, clear the green dragons and kill Morphaz." } },
                    { { t = "Another pack of green dragons hides in the passage at 12 o'clock. Pull and clear it, or it will add onto the final boss." } },
                    { { t = "In the Sanctum of the Fallen God to the west, use " }, { i = "Filled Egg of Hakkar", id = 10662 }, { t = " at the skeleton in the middle to trigger the event." } },
                    { { t = "Back off to the edge and wait for spawns; kill Hakkari Bloodkeepers for Hakkari Blood and use it to put out the four corner braziers." } },
                    { { t = "When Nightmare Suppressors spawn, pull them away and kill them promptly; don't let them pile up at the edge." } },
                    { { t = "Once all four braziers are out, the Avatar of Hakkar descends. Kill it, loot the Essence of Hakkar and right-click it to complete " }, { q = "The God Hakkar", id = 3528 }, { t = "." } },
                    { { t = "Take the southernmost passage to the Hall of the Sleeper and fight the Shade of Eranikus; he puts the current tank to sleep, and it can't be dispelled." } },
                    { { t = "Have someone with Dodge or a pet take second threat. Once the tank is asleep, ranged kite and fight. Don't leave the hall: stepping out drops combat and resets him." } },
                    { { t = "Kill it and loot The Essence of Eranikus, right-click to accept " }, { q = "The Essence of Eranikus", id = 3373 }, { t = ", and turn it in at the Fount of Essence in the corner of the hall." } },
                },
            },
