                    { { t = "Return to Stonard in the Swamp of Sorrows, find " }, { n = "Fel'zerul", id = 1443 }, { t = " and turn in " }, { q = "The Temple of Atal'Hakkar", id = 1445 }, { t = "." } },
                    { { t = "Go to Marshal's Refuge in Un'Goro Crater and turn in " }, { q = "Zapper Fuel", id = 4146 }, { t = " to Larion." } },
