        secA = {
            {
                hd = "Before the Dungeon",
                st = {
                    { { t = "Go to the inn in the Dwarven District of Stormwind, find " }, { n = "Brohann Caskbelly", id = 5384 }, { t = " and accept " }, { q = "To The Hinterlands", id = 1449 }, { t = "." } },
                    { { t = "Go to Aerie Peak in The Hinterlands and turn it in to Falstad Wildhammer, then find the caretaker in the house behind the flight path to continue." } },
                    { { t = "Do what the caretaker asks, then find Rhapsody Shindigger on the trail from The Hinterlands to the Western Plaguelands." } },
                    { { t = "After running his whole series, find him in The Hinterlands and turn in " }, { q = "Rhapsody's Tale", id = 1469 }, { t = "." } },
                    { { t = "Return to the Stormwind inn and accept " }, { q = "Into The Temple of Atal'Hakkar", id = 1475 }, { t = " from " }, { n = "Brohann Caskbelly", id = 5384 }, { t = "; it needs 10 " }, { i = "Atal'ai Tablet", id = 6288 }, { t = "." } },
                    { { t = "The tablets don't require going deep: one underwater in the middle of the entrance hall and one on each side table; wait for respawns to fill up." } },
                    { { t = "Find " }, { n = "Angelas Moonbreeze", id = 7900 }, { t = " at Feathermoon Stronghold in Feralas and accept " }, { q = "The Sunken Temple", id = 3445 }, { t = "." } },
                    { { t = "Outside Tanaris at 52,45, turn in " }, { q = "The Sunken Temple", id = 3445 }, { t = " to " }, { n = "Marvon Rivetseeker", id = 7771 }, { t = ", then accept " }, { q = "Into the Depths", id = 3446 }, { t = " and " }, { q = "Secret of the Circle", id = 3447 }, { t = "." } },
                    { { t = "In Steamwheedle Port accept " }, { q = "The God Hakkar", id = 3528 }, { t = " from " }, { n = "Yeh'kinya", id = 8579 }, { t = "; the prerequisite is " }, { q = "The Ancient Egg", id = 4787 }, { t = " from Zul'Farrak." } },
                    { { t = "In Feralas at 45,25 accept " }, { q = "Haze of Evil", id = 4143 }, { t = " from " }, { n = "Gregan Brewspewer", id = 7775 }, { t = "; it needs 5 " }, { i = "Atal'ai Haze", id = 11318 }, { t = "." } },
                },
            },
            {
                hd = "Inside the Dungeon",
                st = {
                    { { t = "The entrance hall has four passages from left to right; the leftmost goes straight to the green dragons and is also the exit after you finish." } },
                    { { t = "The second leads to the troll guardians' galleries, the third to the statue puzzle, and the fourth to the Altar of Hakkar on the lowest level." } },
                    { { t = "Take the rightmost passage first and go down the long spiral stairs to the bottom level." } },
                    { { t = "Find the Altar of Hakkar at the edge of the Pit of Refuse to complete " }, { q = "Into the Depths", id = 3446 }, { t = "." } },
                    { { t = "Clear every mob around the altar. Deep Lurkers and oozes drop " }, { i = "Atal'ai Haze", id = 11318 }, { t = "; collect 5." } },
                    { { t = "Return to the entrance and take the third passage; at the fork go down to the Hall of Solitude and clear the six doorways inside the ring one by one." } },
                    { { t = "After clearing, click the serpent statues in order: 6, 12, 8, 5, 11 and 2 o'clock." } },
                    { { t = "With all six statues lit, the Idol of Hakkar rises from the bottom and Atal'alarion spawns; kill him and click the idol to complete " }, { q = "Secret of the Circle", id = 3447 }, { t = "." } },
                    { { t = "Return to the entrance and take the second passage down to the fourth level; clear in a circle, enter every door on both sides, and kill all six troll guardians." } },
                    { { t = "After the six guardians are cleared, Jammal'an speaks; jump down from the gallery to engage. He mind-controls, so spread out if someone is controlled." } },
                    { { t = "There's also a small green boss nearby; take it out on the way." } },
                    { { t = "Go to the Green Dragon Hall, clear the green dragons and kill Morphaz." } },
                    { { t = "Another pack of green dragons hides in the passage at 12 o'clock. Pull and clear it, or it will add onto the final boss." } },
                    { { t = "In the Sanctum of the Fallen God to the west, use " }, { i = "Filled Egg of Hakkar", id = 10662 }, { t = " at the skeleton in the middle to trigger the event." } },
                    { { t = "Back off to the edge and wait for spawns; kill Hakkari Bloodkeepers for Hakkari Blood and use it to put out the four corner braziers." } },
                    { { t = "When Nightmare Suppressors spawn, pull them away and kill them promptly; don't let them pile up at the edge." } },
                    { { t = "Once all four braziers are out, the Avatar of Hakkar descends. Kill it, loot the Essence of Hakkar and right-click it to complete " }, { q = "The God Hakkar", id = 3528 }, { t = "." } },
                    { { t = "Take the southernmost passage to the Hall of the Sleeper and fight the Shade of Eranikus; he puts the current tank to sleep, and it can't be dispelled." } },
                    { { t = "Have someone with Dodge or a pet take second threat. Once the tank is asleep, ranged kite and fight. Don't leave the hall: stepping out drops combat and resets him." } },
                    { { t = "Kill it and loot The Essence of Eranikus, right-click to accept " }, { q = "The Essence of Eranikus", id = 3373 }, { t = ", and turn it in at the Fount of Essence in the corner of the hall." } },
                },
            },
            {
                hd = "After the Dungeon",
                st = {
                    { { t = "Return to Tanaris and turn in " }, { q = "Into the Depths", id = 3446 }, { t = " and " }, { q = "Secret of the Circle", id = 3447 }, { t = " to " }, { n = "Marvon Rivetseeker", id = 7771 }, { t = "." } },
                    { { t = "Return to the inn in the Stormwind Dwarven District and turn in " }, { q = "Into The Temple of Atal'Hakkar", id = 1475 }, { t = " to " }, { n = "Brohann Caskbelly", id = 5384 }, { t = "." } },
                    { { t = "Go to Marshal's Refuge in Un'Goro Crater and turn in " }, { q = "Haze of Evil", id = 4143 }, { t = " to Muigin." } },
                    { { t = "Return to Steamwheedle Port and turn in " }, { q = "The God Hakkar", id = 3528 }, { t = " to " }, { n = "Yeh'kinya", id = 8579 }, { t = "." } },
                },
            },
        },
    },
    kroldok_stronghold = {
        secA = {
            {
                hd = "Before the Dungeon",
                st = {
                    { { t = "At Farholde Keep in the Riverglades, accept " }, { q = "Saving Sunnyglade", id = 94877 }, { t = " from " }, { n = "Demar Brant" }, { t = "; next to him, accept " }, { q = "Curious Trinkets", id = 94881 }, { t = " and " }, { q = "Scraps of Knowledge", id = 94879 }, { t = " from " }, { n = "Ashe Amberhall" }, { t = "." } },
                    { { t = "All three quests point to Sunnyglade in central Riverglades: kill, collect corpses, pick up items. This is the first step of the zone quest line." } },
                    { { t = "The huge underground cavern beneath Sunnyglade (entrance 45,51, looks like the Karazhan Crypts) also has quests; not sure if they're required, but doing them along the way is recommended for the XP and gold." } },
                    { { t = "After finishing the three in a row, return to town to turn them in and you get a new quest to the Twilight Veil; same routine: accept, do, turn in. Bring a group for the zone's final elite quest." } },
                    { { t = "After finishing the whole Twilight Veil zone, accept the dungeon quest " }, { q = "Twilight Mementos", id = 94983 }, { t = " from " }, { n = "Sergeant Riftan" }, { t = " (Riverglades 30.6,49.1) and collect 8 " }, { i = "Twilight Bangle", id = 267234 }, { t = " inside." } },
                    { { t = "The sergeant also asks you to report back; after three turn-ins in a row at Farholde Keep, accept " }, { q = "Eye of Mugg", id = 94982 }, { t = " from " }, { n = "Demar Brant" }, { t = " and " }, { q = "Tome of Twilight", id = 94984 }, { t = " from " }, { n = "Ashe Amberhall" }, { t = "." } },
                    { { t = "The direct prerequisite for the Tome of Twilight is " }, { q = "A Small Favor", id = 94907 }, { t = ": Ambrohor gives you a soulstone; go to the conduit in the Twilight Veil, capture a cultist minion and bring it back for interrogation." } },
                    { { t = "When you have time, go to the Ruinvivor Lounge in the Dalaran ruins, accept " }, { q = "Vengeance of the Highborne", id = 96771 }, { t = " from the Highborne " }, { n = "Ranath Nightstride" }, { t = ", and kill Zarvan Moonshadow in the dungeon." } },
                    { { t = "With all prerequisites done, group up and enter. The instance portal is due north of Sunnyglade; go up the slope to find ogre-style walls and the meeting stone." } },
                },
            },
            {
                hd = "Inside the Dungeon",
                st = {
                    { { t = "An open-world dungeon you can ride a mount through the whole way. Trash spawns scattered in groups of three, making it a breeze to clear; all orc mobs drop " }, { i = "Twilight Bangle", id = 267234 }, { t = ", collect 8 to complete" }, { q = "Twilight Mementos", id = 94983 }, { t = ", and the mobs are practically endless, so there's no worry about running out." } } ,
                    { { t = "Walk to the obvious downward slope and charge down. Boss 1, Grox the Slavebreaker (patrols the mine), is here. Kill him, grab the loot and go." } },
                    { { t = "Go deeper. In front of a training ground you'll meet boss 2, Twilight Commander Zalmok. Kill him, grab the loot and go." } },
                    { { t = "Past the stone archway you meet a new mob, the Twilight Laborer: when hit it flees to a nearby camp for help, so stop it with Hamstring, Hammer of Justice or similar. Even if it brings adds this dungeon isn't hard, so just clear them." } },
                    { { t = "At the obvious fork keep going straight; in the pen-like area you meet Boss 3, Beastmaster Ashka, and her two wolves. The wolves cast an AoE fear, so don't get feared into extra packs." } },
                    { { t = "Keep going straight to the far end, kill the ogre smith Tunk, loot " }, { i = "Krol'dok Moulding", id = 267138 }, { t = " from the corpse and click it to accept the dungeon quest " }, { q = "Krol'dok Moulding", id = 94980 }, { t = "." } },
                    { { t = "Return to Farholde Keep, give the moulding to " }, { n = "Alphonse Dumas" }, { t = " along with 4 Thick Leather and 12 Iron Bars, and get the key to Krol'dok Stronghold. The key only opens the huge side gate before the end boss as a shortcut, so it's of little use; just take it for the XP." } },
                    { { t = "Go back to Boss 3's fork and take the uphill path to find the dungeon's only Highborne, Zarvan Moonshadow. He patrols between the junction and a nearby hut; if you can't see him, use a /target macro. Kill him to complete " }, { q = "Vengeance of the Highborne", id = 96771 }, { t = "." } },
                    { { t = "Keep climbing around to the edge of the high platform for Boss 4, Nagruk. After the kill loot " }, { i = "Tome of Twilight", id = 267104 }, { t = " from the corpse and complete " }, { q = "Tome of Twilight", id = 94984 }, { t = ". He uses Domination (mind control); a controlled player must be beaten to half health to break free, so be very careful in Hardcore." } },
                    { { t = "Afterwards don't head back down the slope; turn right onto the high middle bridge. Inside the bridge two mobs spawn periodically, nothing dangerous, so fight your way across. At the end of the bridge is Boss 5, Headman Tuf (a fight on the bridge, he periodically summons Krol'dok Brutes as reinforcements); killing him finishes the trap room." } },
                    { { t = "The key you got earlier opens the huge side door under the high bridge, leading straight to the final boss. Useful if you plan to run this instance several times." } },
                    { { t = "Cross the bridge to the largest house; at the very back is Boss 6, the end boss Overlord Mugg. He keeps leaping around during the fight, so watch your positioning; afterwards loot " }, { i = "Eye of Mugg", id = 267086 }, { t = " from the corpse and complete " }, { q = "Eye of Mugg", id = 94982 }, { t = "." } },
                },
            },
            {
                hd = "After the Dungeon",
                st = {
                    { { t = "Leave the dungeon and turn in " }, { q = "Twilight Mementos", id = 94983 }, { t = " to " }, { n = "Sergeant Riftan" }, { t = "; he then gives " }, { q = "Lingering Essence", id = 94997 }, { t = ", asking you to take the relic package back to Farholde Keep. This is the 'wrong dungeon quest' many addons flag, but you're heading back to the keep to turn in anyway, so just accept it." } },
                    { { t = "After Ambrohor cleanses the bag there is one more step, " }, { q = "Curios of Curiosity", id = 94998 }, { t = ": bring the relic bag to Melanie Sable; do it along the way." } },
                    { { t = "Turn in the remaining quests back in town." } },
                },
            },
        },
    },
